{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "17β-Estradiol, the closest analogue sharing the phenolic estrane core, has absolute oral bioavailability of about 5% in humans due to extensive intestinal and hepatic first-pass metabolism; this directly supports F<20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Ethinylestradiol, a 17α-ethinyl estradiol analogue, reaches 25-65% oral bioavailability, but the query lacks the metabolically protective ethinyl group, so this higher-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Estetrol, a polyhydroxylated estrogen, is reported to have high oral bioavailability in humans; this is contradictory evidence, but its lower structural similarity and different metabolic profile reduce its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "2-Methoxyestradiol, a polar estradiol metabolite, has oral bioavailability of only 1-2% in patients, supporting that adding polar substituents to the estradiol scaffold does not improve F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest experimental anchor, 17β-estradiol, has ~5% absolute oral bioavailability in humans; the query retains the same phenolic estrane core and lacks the 17α-ethinyl protection that raises F in ethinylestradiol. Additional polar estradiol derivatives also show low F. Therefore F<20% is better supported despite a favorable physicochemical prior.",
  "evidence_gaps": [
    "No direct pharmacokinetic measurement exists for the query molecule.",
    "The effect of the extra hydroxyl/cyclopropane modification on first-pass metabolism is not directly evidenced.",
    "Estetrol's reported high oral bioavailability introduces uncertainty for polyhydroxylated estrogens."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

